import json
import urllib.request
import urllib.error

BASE = "http://localhost:8099"
TOKEN = open("/tmp/directus-token.txt").read().strip()

def req(method, path, body=None):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(BASE + path, data=data, method=method, headers={
        "Authorization": f"Bearer {TOKEN}",
        "Content-Type": "application/json",
    })
    try:
        with urllib.request.urlopen(r) as resp:
            raw = resp.read()
            return json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        print(f"ERROR {method} {path}: {e.code}")
        print(e.read().decode())
        raise

# --- Add an O2M alias field on people reversing contacts.related_person_id, so permission
# filters can express "am I (the current Directus user) a guardian of this person". ---
print("adding people.guardian_links alias field")
req("POST", "/fields/people", {
    "field": "guardian_links",
    "type": "alias",
    "meta": {
        "interface": "list-o2m",
        "special": ["o2m"],
        "note": "Reverse of contacts.related_person_id - the contacts rows where this person is the minor.",
    },
})

# Find the existing contacts.related_person_id -> people relation and attach the o2m alias.
print("patching contacts.related_person_id relation to set one_field")
req("PATCH", "/relations/contacts/related_person_id", {
    "meta": {"one_field": "guardian_links"},
})

# --- Staff policy: full CRUD on every custom collection, including medical_profiles. ---
collections = [
    "people", "medical_profiles", "contacts", "event_staff", "programs", "sessions",
    "classes", "session_classes", "entry_caps", "registrations", "registration_entries",
]

print("creating Staff policy")
staff_policy = req("POST", "/policies", {
    "name": "Staff",
    "icon": "badge",
    "description": "Full read/write on the people hub, including medical data. Workspace accounts only (native Google OIDC).",
})["data"]

for c in collections:
    for action in ["create", "read", "update", "delete"]:
        req("POST", "/permissions", {
            "policy": staff_policy["id"],
            "collection": c,
            "action": action,
            "permissions": {},
            "validation": {},
            "fields": ["*"],
        })

print("creating Staff role")
req("POST", "/roles", {
    "name": "Staff",
    "icon": "badge",
    "description": "CYC staff. Authenticates via Directus native Google OIDC, provisioned by an admin.",
})
staff_role = req("GET", "/roles?filter[name][_eq]=Staff")["data"][0]
req("POST", "/access", {"role": staff_role["id"], "policy": staff_policy["id"]})

# --- Coach policy: KISS read-only roster access, no medical data. ---
print("creating Coach policy")
coach_policy = req("POST", "/policies", {
    "name": "Coach",
    "icon": "sports",
    "description": "Read-only roster access (sessions/registration_entries/people). No medical_profiles. Not scoped to the coach's own sessions yet - KISS for now.",
})["data"]

for c in ["sessions", "registration_entries", "people", "programs", "classes"]:
    req("POST", "/permissions", {
        "policy": coach_policy["id"],
        "collection": c,
        "action": "read",
        "permissions": {},
        "fields": ["*"],
    })

print("creating Coach role")
req("POST", "/roles", {
    "name": "Coach",
    "icon": "sports",
    "description": "Coaches. No login yet - needs #65's account-linking.",
})
coach_role = req("GET", "/roles?filter[name][_eq]=Coach")["data"][0]
req("POST", "/access", {"role": coach_role["id"], "policy": coach_policy["id"]})

# --- Guardian policy: read own minors' people/medical_profiles/registrations/registration_entries,
# filtered through the guardian_links alias (contacts where relationship_type == guardian). ---
def guardian_filter(path_to_guardian_links):
    return {
        path_to_guardian_links: {
            "_and": [
                {"relationship_type": {"_eq": "guardian"}},
                {"person_id": {"directus_user_id": {"_eq": "$CURRENT_USER"}}},
            ]
        }
    }

print("creating Guardian policy")
guardian_policy = req("POST", "/policies", {
    "name": "Guardian",
    "icon": "family_restroom",
    "description": "Read own minors' people/medical_profiles/registrations/registration_entries. Filtered through contacts. No login yet - needs #65's account-linking.",
})["data"]

guardian_perms = [
    ("people", guardian_filter("guardian_links")),
    ("medical_profiles", guardian_filter("person_id.guardian_links")),
    ("registrations", guardian_filter("person_id.guardian_links")),
    ("registration_entries", guardian_filter("registration_id.person_id.guardian_links")),
]
for collection, perm_filter in guardian_perms:
    req("POST", "/permissions", {
        "policy": guardian_policy["id"],
        "collection": collection,
        "action": "read",
        "permissions": perm_filter,
        "fields": ["*"],
    })

print("creating Guardian role")
req("POST", "/roles", {
    "name": "Guardian",
    "icon": "family_restroom",
    "description": "Guardians. No login yet - needs #65's account-linking.",
})
guardian_role = req("GET", "/roles?filter[name][_eq]=Guardian")["data"][0]
req("POST", "/access", {"role": guardian_role["id"], "policy": guardian_policy["id"]})

print("Done: Staff, Coach, Guardian roles/policies created.")

